*/
scwin.ipt_selectUrlTp_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_selectUrlTp_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.selected()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70020.ipt_selectUrlTp_onclick' }); }
};

