/**
 * @event
 * @name scwin.__on_enter_3_ipt_linkURL
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.__on_enter_3_ipt_linkURL = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin __on_enter_3_ipt_linkURL — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if(($c.util.getKeyCode(ev))==13){ await $c.win.alert('입력완료를 클릭하세요.') }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70020.__on_enter_3_ipt_linkURL' }); }
};

/**
 * @method
 * @name scwin.getCheckedValue
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj
 * @returns
 * @hidden N
*/
scwin.getCheckedValue = function (_obj) {
    /* sdd-asis-lifecycle:begin fn_GetCheckedValue — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let checkedValue = '';
    for (let i = 0; i < _obj.getItemCount(); i++) {
        if (_obj[i].checked) {
            checkedValue = _obj[i].value;
            break;
        }
    }
    return checkedValue;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.selected
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.selected = function () {
    /* sdd-asis-lifecycle:begin fn_selected — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const selectUrlTpVal = (String(($c.util.getComponent('ipt_selectUrlTp'))?.getValue?.() ?? "").split(" ")[0] ?? "");
    if (selectUrlTpVal === 'Y') {
        $c.util.getComponent('ipt_linkURL').setDisabled(false);
    } else {
        if (selectUrlTpVal === 'N') {
            $c.util.getComponent("ipt_linkURL").setValue("");
            $c.util.getComponent('ipt_linkURL').setDisabled(true);
        } else {
            $c.util.getComponent('ipt_linkURL').setDisabled(false);
        }
    }
    /* sdd-asis-lifecycle:end */
};


